const codes: Record<string, string> = Object.fromEntries(entries.map(entry => [entry.id, entry.code]))
const query = ref('')
const dark = ref(false)
const ready = ref(false)
const visibleCount = computed(() => entries.filter(entry => matches(entry.id)).length)
function matches(id: string) {
  const term = query.value.trim().toLowerCase()
  if (!term) return true
  const entry = entries.find(item => item.id === id)
  return !!entry && (entry.name.toLowerCase().includes(term) || entry.category.toLowerCase().includes(term))
}
function toggleTheme() { dark.value = document.documentElement.classList.toggle('dark') }
onMounted(() => { dark.value = document.documentElement.classList.contains('dark'); ready.value = true })
